package com.guocheng.mediapocket;
import android.content.Context;import dalvik.system.DexClassLoader;import com.github.catvod.crawler.Spider;import org.json.*;import java.net.*;import java.io.*;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.*;
/** CatVod/QuickJS host. Derived loading protocol from FongMi/TV; see RUNTIME-LICENSE.md. */
final class TvSpiderRuntime {
 static volatile TvSpiderRuntime instance;final Context context;final Map<String,DexClassLoader> loaders=new LinkedHashMap<>();final Map<String,Spider> spiders=new LinkedHashMap<>();final Map<String,Method> proxies=new LinkedHashMap<>();final ThreadPoolExecutor calls=new ThreadPoolExecutor(2,4,20,TimeUnit.SECONDS,new ArrayBlockingQueue<>(12));final ThreadPoolExecutor streams=new ThreadPoolExecutor(2,4,20,TimeUnit.SECONDS,new ArrayBlockingQueue<>(12));volatile String recent="";ServerSocket server;
 static synchronized TvSpiderRuntime get(Context c)throws Exception{if(instance==null)instance=new TvSpiderRuntime(c.getApplicationContext());return instance;}
 TvSpiderRuntime(Context c)throws Exception{context=c;com.github.catvod.Init.set(c);server=new ServerSocket(0,16,InetAddress.getByName("127.0.0.1"));com.github.catvod.Proxy.set(server.getLocalPort());Thread accept=new Thread(()->{while(!server.isClosed())try{Socket socket=server.accept();try{streams.execute(()->serve(socket));}catch(RejectedExecutionException e){socket.close();}}catch(Exception e){break;}},"CatVodProxy");accept.setDaemon(true);accept.start();}
 byte[] download(String url)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(12000);c.setReadTimeout(20000);c.setRequestProperty("User-Agent","Mozilla/5.0");try{if(c.getResponseCode()!=200)throw new IOException("组件下载返回 HTTP "+c.getResponseCode());try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(Thread.currentThread().isInterrupted())throw new IOException("加载已取消");if(out.size()+n>16*1024*1024)throw new IOException("组件过大");out.write(b,0,n);}return out.toByteArray();}}finally{c.disconnect();}}
 synchronized DexClassLoader jar(String declaration,String base)throws Exception{if(declaration.isEmpty())return null;String url=TvBoxRules.resolve(base,declaration),md5=TvSpiderRules.md5(declaration),key=url+";"+md5;DexClassLoader existing=loaders.get(key);if(existing!=null)return existing;byte[] bytes=download(url);TvSpiderRules.verify(bytes,md5);String digest=TvSpiderRules.digest(bytes,"SHA-256");File dir=new File(context.getCodeCacheDir(),"tvbox-runtime");if(!dir.exists()&&!dir.mkdirs())throw new IOException("无法创建组件缓存");File file=new File(dir,digest+".jar");if(!file.isFile()){File temp=File.createTempFile("component-",".jar",dir);try{try(FileOutputStream out=new FileOutputStream(temp)){if(!temp.setReadOnly())throw new IOException("无法保护组件文件");out.write(bytes);out.getFD().sync();}if(!temp.renameTo(file))throw new IOException("无法保存组件文件");}finally{if(temp.exists())temp.delete();}}if(!file.setReadOnly())throw new IOException("组件文件保护失败");DexClassLoader loader=new DexClassLoader(file.getAbsolutePath(),dir.getAbsolutePath(),context.getApplicationInfo().nativeLibraryDir,context.getClassLoader());try{Class<?> init=loader.loadClass("com.github.catvod.spider.Init");init.getMethod("init",Context.class).invoke(null,context);}catch(ClassNotFoundException ignored){}catch(InvocationTargetException e){throw new IOException("组件初始化失败："+e.getCause().getClass().getSimpleName(),e.getCause());}try{proxies.put(key,loader.loadClass("com.github.catvod.spider.Proxy").getMethod("proxy",Map.class));}catch(ClassNotFoundException|NoSuchMethodException ignored){}loaders.put(key,loader);return loader;}
 synchronized Spider spider(JSONObject config,JSONObject site,String base)throws Exception{String declaration=site.optString("jar",config.optString("spider")),api=site.optString("api"),key=TvSpiderRules.digest((base+"|"+site.toString()+"|"+declaration).getBytes("UTF-8"),"SHA-256");String jarKey=declaration.isEmpty()?"":TvBoxRules.resolve(base,declaration)+";"+TvSpiderRules.md5(declaration);recent=jarKey;Spider existing=spiders.get(key);if(existing!=null)return existing;DexClassLoader loader=jar(declaration,base);Spider result;if(api.startsWith("csp_")){if(loader==null)throw new IOException("站点缺少爬虫组件");result=(Spider)loader.loadClass(TvSpiderRules.className(api)).getDeclaredConstructor().newInstance();}else{result=new com.fongmi.quickjs.crawler.Loader().spider(TvBoxRules.resolve(base,api),loader);}result.siteKey=site.optString("key");Object ext=site.opt("ext");String argument=ext==null?"":ext instanceof String?(String)ext:ext.toString();if(argument.startsWith("./")||argument.startsWith("../"))argument=TvBoxRules.resolve(base,argument);result.init(context,argument);spiders.put(key,result);return result;}
 JSONObject request(JSONObject config,JSONObject site,String base,String operation,String value,String flag,int page)throws Exception{Future<String> job;try{job=calls.submit(()->{Spider s=spider(config,site,base);synchronized(s){List<String> vip=new ArrayList<>();JSONArray flags=config.optJSONArray("flags");if(flags!=null)for(int i=0;i<flags.length();i++)vip.add(flags.optString(i));return TvSpiderDispatch.invoke(s,operation,value,flag,page,vip);}});}catch(RejectedExecutionException e){throw new IOException("线路任务繁忙，请稍候重试");}try{String text=job.get(35,TimeUnit.SECONDS);if(text==null||text.trim().isEmpty())throw new IOException("线路返回空数据");return new JSONObject(text);}catch(TimeoutException e){job.cancel(true);throw new IOException("线路调用超过 35 秒");}catch(ExecutionException e){Throwable cause=e.getCause();throw new IOException("线路组件错误："+cause.getClass().getSimpleName(),cause);}catch(InterruptedException e){job.cancel(true);Thread.currentThread().interrupt();throw new IOException("线路调用已取消");}}
 Object[] proxy(Map<String,String> params)throws Exception{List<Method> methods;List<Spider> js;synchronized(this){methods=new ArrayList<>();Method first=proxies.get(recent);if(first!=null)methods.add(first);for(Method m:proxies.values())if(m!=first)methods.add(m);js=new ArrayList<>(spiders.values());}for(Spider s:js)if(s instanceof com.fongmi.quickjs.crawler.Spider){Object[] value=s.proxy(params);if(value!=null)return value;}for(Method m:methods)try{Object[] value=(Object[])m.invoke(null,params);if(value!=null)return value;}catch(Exception ignored){}return null;}
 void serve(Socket socket){try(Socket client=socket){client.setSoTimeout(15000);BufferedReader in=new BufferedReader(new InputStreamReader(client.getInputStream(),"US-ASCII"));String line=readLine(in);if(line==null)return;String[] parts=line.split(" ");if(parts.length<2)return;String path=parts[1];if(!path.startsWith("/proxy")){respond(client,"404 Not Found",new byte[0],null,false);return;}Map<String,String> params=new HashMap<>();int q=path.indexOf('?');if(q>=0)for(String pair:path.substring(q+1).split("&")){String[] kv=pair.split("=",2);params.put(URLDecoder.decode(kv[0],"UTF-8"),kv.length>1?URLDecoder.decode(kv[1],"UTF-8"):"");}for(int i=0;i<40;i++){line=readLine(in);if(line==null||line.isEmpty())break;int at=line.indexOf(':');if(at>0&&line.substring(0,at).equalsIgnoreCase("Range"))params.put("range",line.substring(at+1).trim());}Object[] response=proxy(params);if(response==null||response.length<3){respond(client,"502 Bad Gateway",new byte[0],null,false);return;}int code=response[0] instanceof Number?((Number)response[0]).intValue():Integer.parseInt(response[0].toString());String type=response[1].toString().replace("\r","").replace("\n","");InputStream body=response[2] instanceof InputStream?(InputStream)response[2]:new ByteArrayInputStream(response[2].toString().getBytes("UTF-8"));OutputStream out=client.getOutputStream();String headers="HTTP/1.1 "+code+" OK\r\nContent-Type: "+type+"\r\nConnection: close\r\n";if(response.length>3&&response[3] instanceof Map)for(Object entry:((Map)response[3]).entrySet()){Map.Entry e=(Map.Entry)entry;String name=e.getKey().toString();if(name.equalsIgnoreCase("Content-Length")||name.equalsIgnoreCase("Content-Range")||name.equalsIgnoreCase("Accept-Ranges"))headers+=name+": "+e.getValue().toString().replace("\r","").replace("\n","")+"\r\n";}out.write((headers+"\r\n").getBytes("US-ASCII"));try(InputStream input=body){byte[] b=new byte[16384];int n;while((n=input.read(b))!=-1)out.write(b,0,n);}out.flush();}catch(Throwable ignored){}}
 static String readLine(BufferedReader in)throws Exception{StringBuilder b=new StringBuilder();int c;while((c=in.read())!=-1){if(c=='\n')break;if(b.length()>=8192)throw new IOException("header too long");if(c!='\r')b.append((char)c);}return c==-1&&b.length()==0?null:b.toString();}
 static void respond(Socket client,String status,byte[] data,String redirect,boolean head)throws Exception{OutputStream out=client.getOutputStream();out.write(("HTTP/1.1 "+status+"\r\nContent-Length: "+data.length+"\r\nConnection: close\r\n\r\n").getBytes("US-ASCII"));if(!head)out.write(data);out.flush();}
}
